// Vault: конфиг капсулы, реестр участников, котёл (tsTON) и накопительный счётчик acc.
// DESIGN.md §3.1, §4. Администратора и апгрейда нет (I5).

import "constants"
import "errors"
import "messages"
import "storage"
import "tonstakers"
import "window"

contract Vault {
    author: "lock-in-wallet"
    version: "0.1.0"
    description: "Lock-in Wallet vault: schedule, member registry, cauldron (tsTON) with acc counter"
    storage: VaultStorage
    incomingMessages: VaultMessage
}

type VaultMessage =
    | Deposit
    | StakeForfeits
    | ExitNotice
    | TrancheCancelled
    | TrancheActivated
    | Forfeit
    | ExitReport
    | JettonTransferNotification
    | Excesses
    | TopUp

// ---------- helpers ----------

fun VaultStorage.accountInit(self, owner: address): AutoDeployAddress {
    return calcAccountInit(contract.getAddress(), owner, self.accountCode, self.accountParams);
}

fun VaultStorage.assertFromAccount(self, sender: address, owner: address) {
    assert (sender == self.accountInit(owner).calculateAddress()) throw Errors.NotMemberAccount;
}

fun VaultStorage.tstonWallet(self): address {
    val params = self.accountParams.load();
    return calcTsTonWalletAddress(
        contract.getAddress(),
        params.tstonMaster,
        params.tstonWalletCode,
    );
}

fun VaultStorage.window(self): WindowState {
    return calcWindowState(self.period, self.windowLength, self.epochStart, blockchain.now());
}

/// Разнести tsTON котла в acc (I4). Если активных вкладов нет — в unallocated до следующего раза.
fun VaultStorage.distribute(mutate self, tokens: coins) {
    if (self.totalPrincipal > 0) {
        val total = tokens + self.unallocated;
        self.acc += (total << ACC_SCALE_BITS) / self.totalPrincipal;
        self.unallocated = 0;
    } else {
        self.unallocated += tokens;
    }
}

/// Отправить накопленные форфейты в пул, если буфер ≥ FORFEIT_STAKE_MIN и хватает на комиссию пула.
fun VaultStorage.tryStakeForfeits(mutate self) {
    if (self.pendingStake != 0 || self.forfeitBuffer < FORFEIT_STAKE_MIN) {
        return;
    }
    val needed = self.forfeitBuffer + POOL_DEPOSIT_FEE + VAULT_MIN_BALANCE;
    if (contract.getOriginalBalance() < needed) {
        return;
    }
    val params = self.accountParams.load();
    val amount = self.forfeitBuffer;
    val stake = createMessage({
        bounce: BounceMode.Only256BitsOfBody,
        dest: params.pool,
        value: amount + POOL_DEPOSIT_FEE,
        body: PoolDeposit { queryId: 0 },
    });
    stake.send(SEND_MODE_PAY_FEES_SEPARATELY);
    self.pendingStake = amount;
    self.forfeitBuffer = 0;
    emitLog(
        0x344b89ee,
        LogForfeitStaked {
            queryId: 0,
            amount,
        },
    );
}

fun sendExitAck(
    to: address,
    queryId: uint64,
    mode: int,
    bonus: coins,
    value: coins,
    sendMode: int,
) {
    val ack = createMessage({
        bounce: BounceMode.NoBounce,
        dest: to,
        value,
        body: ExitAck { queryId, mode, bonus },
    });
    ack.send(sendMode);
}

// ---------- bounces ----------

fun onBouncedMessage(in: InMessageBounced) {
    val prefix = in.bouncedBody.preloadUint(32);
    if (prefix == 0xffffffff) {
        // Only256BitsOfBody: единственный такой исходящий — deposit форфейтов в пул
        in.bouncedBody.skipBouncedPrefix();
        val op = in.bouncedBody.loadUint(32);
        if (op == 0x47d54391) {
            var storage = VaultStorage.load();
            storage.forfeitBuffer += storage.pendingStake;
            storage.pendingStake = 0;
            storage.save();
        }
        return;
    }

    val rich = lazy RichBounceBody.fromSlice(in.bouncedBody);
    var body = rich.originalBody.beginParse();
    val op = body.loadUint(32);
    var storage = VaultStorage.load();

    if (op == 0x5ce33f6f) {
        // credit_tranche отбит: вернуть principal из total_principal, TON — владельцу
        val queryId = body.loadUint(64);
        val principal = body.loadCoins();
        body.skipBits(128 + 32);
        val owner = body.loadAddress();
        storage.totalPrincipal = max(storage.totalPrincipal - principal, 0);
        storage.save();
        val refund = createMessage({
            bounce: BounceMode.NoBounce,
            dest: owner,
            value: 0,
            body: TrancheCancelled {
                queryId,
                owner,
                principal,
                slot: 255,
            },
        });
        refund.send(SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE | SEND_MODE_IGNORE_ERRORS);
        emitLog(
            0x1da026e0,
            LogTrancheCancelled {
                queryId,
                owner,
                principal,
                slot: 255,
            },
        );
        return;
    }

    if (op == 0x0f8a7ea5) {
        // бонус-жетон не доставлен: вернуть токены в котёл, аккаунт разблокировать exit_ack{bonus=0}
        val queryId = body.loadUint(64);
        val bonus = body.loadCoins();
        val account = body.loadAddress();
        storage.distribute(bonus);
        storage.save();
        sendExitAck(
            account,
            queryId,
            MODE_FULL,
            0,
            0,
            SEND_MODE_CARRY_ALL_REMAINING_MESSAGE_VALUE,
        );
        return;
    }
}

// ---------- messages ----------

fun onInternalMessage(in: InMessage) {
    val msg = lazy VaultMessage.fromSlice(in.body);

    match (msg) {
        Deposit => {
            assert (in.senderAddress.getWorkchain() == MY_WORKCHAIN) throw Errors.WrongWorkchain;
            assert (msg.amount >= MIN_DEPOSIT) throw Errors.DepositTooSmall;
            assert (
                in.valueCoins >= msg.amount + POOL_DEPOSIT_FEE + DEPOSIT_GAS
            ) throw Errors.NotEnoughGas;

            var storage = VaultStorage.load();
            storage.totalPrincipal += msg.amount;
            val now = blockchain.now();
            val accountInit = storage.accountInit(in.senderAddress);

            val credit = createMessage({
                bounce: BounceMode.RichBounce,
                dest: accountInit,
                value: in.valueCoins - VAULT_GAS_CUT,
                body: CreditTranche {
                    queryId: msg.queryId,
                    principal: msg.amount,
                    acc0: storage.acc,
                    depositedAt: now,
                    owner: in.senderAddress,
                },
            });
            credit.send(SEND_MODE_PAY_FEES_SEPARATELY);
            storage.save();

            emitLog(
                0x85b4434a,
                LogDeposited {
                    queryId: msg.queryId,
                    owner: in.senderAddress,
                    account: accountInit.calculateAddress(),
                    principal: msg.amount,
                },
            );
        }

        ExitNotice => {
            var storage = VaultStorage.load();
            storage.assertFromAccount(in.senderAddress, msg.owner);
            assert (storage.totalPrincipal >= msg.principalSum) throw Errors.PrincipalUnderflow;

            val window = storage.window();
            val remaining = storage.totalPrincipal - msg.principalSum;
            val full = window.isOpen || remaining == 0; // I6: последнему некому отдавать

            if (!full && !msg.forceEarly) {
                val rejected = createMessage({
                    bounce: BounceMode.NoBounce,
                    dest: in.senderAddress,
                    value: in.valueCoins - VAULT_GAS_CUT,
                    body: ExitRejected {
                        queryId: msg.queryId,
                        nextWindowAt: window.nextWindowAt,
                    },
                });
                rejected.send(SEND_MODE_PAY_FEES_SEPARATELY);
                emitLog(
                    0x9f2b0f1e,
                    LogExitRejected {
                        queryId: msg.queryId,
                        owner: msg.owner,
                        nextWindowAt: window.nextWindowAt,
                    },
                );
                return;
            }

            var share = (msg.principalSum * storage.acc - msg.debtSum) >> ACC_SCALE_BITS;
            if (share < 0) {
                share = 0;
            }
            storage.totalPrincipal = remaining;

            if (full) {
                if (share > 0) {
                    val value = in.valueCoins - VAULT_GAS_CUT;
                    val transfer = createMessage({
                        bounce: BounceMode.RichBounce,
                        dest: storage.tstonWallet(),
                        value,
                        body: JettonTransfer {
                            queryId: msg.queryId,
                            jettonAmount: share,
                            destination: in.senderAddress,
                            responseDestination: in.senderAddress,
                            customPayload: null,
                            forwardTonAmount: value - JETTON_TRANSFER_RESERVE,
                            forwardPayload: beginCell().storeUint(0, 1).endCell().beginParse(),
                        },
                    });
                    transfer.send(SEND_MODE_PAY_FEES_SEPARATELY);
                } else {
                    sendExitAck(
                        in.senderAddress,
                        msg.queryId,
                        MODE_FULL,
                        0,
                        in.valueCoins - VAULT_GAS_CUT,
                        SEND_MODE_PAY_FEES_SEPARATELY,
                    );
                }
                emitLog(
                    0x72d5e9ca,
                    LogExitStarted {
                        queryId: msg.queryId,
                        owner: msg.owner,
                        mode: MODE_FULL,
                        slots: msg.slots,
                        principalSum: msg.principalSum,
                        bonus: share,
                    },
                );
            } else {
                // I2: доля котла ушедшего остаётся в котле и делится между оставшимися
                storage.distribute(share);
                sendExitAck(
                    in.senderAddress,
                    msg.queryId,
                    MODE_EARLY,
                    0,
                    in.valueCoins - VAULT_GAS_CUT,
                    SEND_MODE_PAY_FEES_SEPARATELY,
                );
                emitLog(
                    0x72d5e9ca,
                    LogExitStarted {
                        queryId: msg.queryId,
                        owner: msg.owner,
                        mode: MODE_EARLY,
                        slots: msg.slots,
                        principalSum: msg.principalSum,
                        bonus: 0,
                    },
                );
            }
            storage.save();
        }

        TrancheCancelled => {
            var storage = VaultStorage.load();
            storage.assertFromAccount(in.senderAddress, msg.owner);
            storage.totalPrincipal = max(storage.totalPrincipal - msg.principal, 0);
            storage.save();
            emitLog(
                0x1da026e0,
                LogTrancheCancelled {
                    queryId: msg.queryId,
                    owner: msg.owner,
                    principal: msg.principal,
                    slot: msg.slot,
                },
            );
        }

        TrancheActivated => {
            var storage = VaultStorage.load();
            storage.assertFromAccount(in.senderAddress, msg.owner);
            if (msg.first) {
                storage.memberCount += 1;
            }
            storage.save();
            emitLog(
                0xd4592eba,
                LogTrancheActivated {
                    queryId: msg.queryId,
                    owner: msg.owner,
                    slot: msg.slot,
                    principal: msg.principal,
                    tokens: msg.tokens,
                    memberJoined: msg.first,
                    memberCount: storage.memberCount,
                },
            );
        }

        Forfeit => {
            var storage = VaultStorage.load();
            storage.assertFromAccount(in.senderAddress, msg.owner);
            assert (in.valueCoins >= msg.amount) throw Errors.NotEnoughGas;
            storage.forfeitBuffer += msg.amount;
            storage.tryStakeForfeits();
            storage.save();
        }

        ExitReport => {
            var storage = VaultStorage.load();
            storage.assertFromAccount(in.senderAddress, msg.owner);
            assert (in.valueCoins >= msg.forfeit) throw Errors.NotEnoughGas;
            storage.forfeitBuffer += msg.forfeit;
            if (!msg.hasTranches && storage.memberCount > 0) {
                storage.memberCount -= 1;
            }
            storage.tryStakeForfeits();
            storage.save();
            emitLog(
                0x72208540,
                LogExited {
                    queryId: msg.queryId,
                    owner: msg.owner,
                    mode: msg.mode,
                    slots: msg.slots,
                    payout: msg.payout,
                    forfeit: msg.forfeit,
                    hasTranches: msg.hasTranches,
                    memberCount: storage.memberCount,
                },
            );
        }

        StakeForfeits => {
            var storage = VaultStorage.load();
            storage.tryStakeForfeits();
            storage.save();
        }

        JettonTransferNotification => {
            // tsTON пришли на кошелёк Vault: стейк форфейтов (from == none) или пожертвование
            var storage = VaultStorage.load();
            assert (in.senderAddress == storage.tstonWallet()) throw Errors.NotTstonWallet;
            if (msg.from == null) {
                storage.pendingStake = 0;
            }
            storage.distribute(msg.jettonAmount);
            storage.save();
        }

        Excesses => {
            // возврат комиссии пула после стейка форфейтов: остаётся на балансе Vault
        }

        TopUp => {}

        else => {
            assert (in.body.isEmpty()) throw Errors.InvalidMessage;
        }
    }
}

// ---------- get-методы ----------

struct VaultConfigReply {
    period: uint32
    windowLength: uint32
    epochStart: uint32
    pool: address
    tstonMaster: address
    vaultTstonWallet: address
    memberCount: uint32
    totalPrincipal: coins
    acc: uint128
    unallocated: coins
    forfeitBuffer: coins
    pendingStake: coins
}

get fun get_config(): VaultConfigReply {
    val storage = VaultStorage.load();
    val params = storage.accountParams.load();
    return {
        period: storage.period,
        windowLength: storage.windowLength,
        epochStart: storage.epochStart,
        pool: params.pool,
        tstonMaster: params.tstonMaster,
        vaultTstonWallet: storage.tstonWallet(),
        memberCount: storage.memberCount,
        totalPrincipal: storage.totalPrincipal,
        acc: storage.acc,
        unallocated: storage.unallocated,
        forfeitBuffer: storage.forfeitBuffer,
        pendingStake: storage.pendingStake,
    };
}

get fun get_window(): WindowState {
    val storage = VaultStorage.load();
    return storage.window();
}

get fun get_account_address(owner: address): address {
    val storage = VaultStorage.load();
    return storage.accountInit(owner).calculateAddress();
}

// Общие константы протокола капсулы. Значения газа — первичные оценки,
// уточняются по профилю `acton test --gas-profile` (см. PLAN.md §5).

const MY_WORKCHAIN = BASECHAIN

/// Минимальный вклад: минимум депозита Tonstakers (DESIGN §5, §7.2).
const MIN_DEPOSIT = ton("1")

/// Слотов траншей на аккаунт (DESIGN §3.2): битовая маска uint64.
const MAX_TRANCHES = 64

/// Множитель накопительного счётчика acc (DESIGN §4.4): 2^64.
const ACC_SCALE_BITS = 64

/// Комиссия депозита Tonstakers: пул удерживает ровно 1 TON и возвращает остаток excesses (§7.2).
const POOL_DEPOSIT_FEE = ton("1")

/// Сколько TON должно дойти до пула вместе с burn (§7.3: > 0.5 TON, SDK прикладывает 1.05).
const POOL_BURN_VALUE_MIN = ton("1.05")

/// Газ цепочки депозита сверх `amount + POOL_DEPOSIT_FEE`: Vault → Account(deploy) → pool → mint → notification.
const DEPOSIT_GAS = ton("0.3")

/// Газ цепочки выхода: exit_notice → (бонус jetton) → burn → выплата → exit_report.
const WITHDRAW_GAS = ton("1.5")

/// Газ повторного burn (retry_exit).
const RETRY_GAS = ton("1.2")

/// Газ ручного триггера стейка котла.
const STAKE_FORFEITS_GAS = ton("0.1")

/// Резерв аккаунта на хранение (капсула бессрочна, §4.5).
const ACCOUNT_MIN_BALANCE = ton("0.1")

/// Сверх резерва аккаунта: всё, что выше `ACCOUNT_MIN_BALANCE + SWEEP_THRESHOLD`
/// при withdraw считается неатрибутированным TON и уходит в котёл (§7.3 п. 3).
const SWEEP_THRESHOLD = ton("0.2")

/// Резерв Vault на хранение и газ.
const VAULT_MIN_BALANCE = ton("0.5")

/// Порог стейка котла (§4.4): меньше — комиссия пула съедает смысл.
const FORFEIT_STAKE_MIN = ton("1")

/// Что Vault оставляет себе с каждого проходящего сообщения на газ (deposit, exit_notice).
const VAULT_GAS_CUT = ton("0.02")

/// Газ, который аккаунт прикладывает к служебным сообщениям в Vault (отчёты, отмены).
const REPORT_GAS = ton("0.03")

/// Запас на два jetton-хопа при переводе бонуса из Vault в аккаунт: сколько TON НЕ уходит в forward_ton_amount.
const JETTON_TRANSFER_RESERVE = ton("0.12")

/// Что аккаунт оставляет от входящего value при отправке burn (газ этой транзакции и forward fee).
const BURN_TX_RESERVE = ton("0.02")

/// Отложенная выплата принимается, если value ≥ P_sum × 90 % (§7.3 п. 2).
const DEFERRED_PAYOUT_MIN_PERCENT = 90

/// Через сколько владелец может повторить burn (§7.3, retry_exit): 3 суток.
const RETRY_TIMEOUT = 3 * 24 * 3600

/// Статусы транша (DESIGN §3.2).
const TRANCHE_STAKING = 0
const TRANCHE_ACTIVE = 1
const TRANCHE_EXITING = 2

/// Режимы pending-батча (DESIGN §3.2).
const MODE_AWAITING_ACK = 0
const MODE_EARLY = 1
const MODE_FULL = 2

// Сообщения капсулы. Опкоды = crc32 имени (см. INTERFACE.md).
// ---------- пользователь → Vault ----------

/// deposit: внести `amount` TON; value ≥ amount + POOL_DEPOSIT_FEE + DEPOSIT_GAS.
struct (0x95db9d39) Deposit {
    queryId: uint64
    amount: coins
}

/// stake_forfeits: ручной триггер стейка котла (любой отправитель).
struct (0x959c593e) StakeForfeits {
    queryId: uint64
}

// ---------- Vault → MemberAccount ----------

/// credit_tranche: новый транш (+stateInit при первом депозите).
struct (0x5ce33f6f) CreditTranche {
    queryId: uint64
    principal: coins
    acc0: uint128
    depositedAt: uint32
    owner: address // для возврата TON при bounce
}

/// exit_ack: решение Vault по батчу (mode = MODE_EARLY | MODE_FULL, bonus = tsTON, уже отправленные аккаунту или 0).
struct (0x4fccc930) ExitAck {
    queryId: uint64
    mode: uint2
    bonus: coins
}

/// exit_rejected: окно закрыто, force_early не задан.
struct (0xa0465851) ExitRejected {
    queryId: uint64
    nextWindowAt: uint32
}

// ---------- MemberAccount → Vault ----------

/// tranche_cancelled: депозит в пул отбился (или нет свободного слота: slot = 255),
/// транш удалён, TON возвращён владельцу.
struct (0xd1116e69) TrancheCancelled {
    queryId: uint64
    owner: address
    principal: coins
    slot: uint8
}

/// tranche_activated: транш подтверждён стейком; first = аккаунт стал участником.
struct (0x18e86633) TrancheActivated {
    queryId: uint64
    owner: address
    slot: uint8
    principal: coins
    tokens: coins
    first: bool
}

/// exit_notice: аккаунт просит решение по батчу.
struct (0x5b129b50) ExitNotice {
    queryId: uint64
    owner: address
    slots: uint64
    principalSum: coins
    debtSum: uint256
    forceEarly: bool
}

/// forfeit: TON в котёл (неатрибутированный TON при sweep); value ≥ amount + газ.
struct (0xbcbc6c5e) Forfeit {
    queryId: uint64
    owner: address
    amount: coins
}

/// exit_report: выплата произведена; forfeit — TON в котёл (value ≥ forfeit + газ).
struct (0xd730a916) ExitReport {
    queryId: uint64
    owner: address
    mode: uint2
    slots: uint64
    payout: coins
    forfeit: coins
    hasTranches: bool
}

// ---------- пользователь → MemberAccount ----------

/// withdraw: вывести транши по маске слотов; value ≥ WITHDRAW_GAS.
struct (0xb5de5f9e) Withdraw {
    queryId: uint64
    slots: uint64
    forceEarly: bool
}

/// retry_exit: повторить burn тем же batch_id через RETRY_TIMEOUT.
struct (0x770cf851) RetryExit {
    queryId: uint64
}

/// top_up: пополнить баланс контракта (Vault или аккаунт); пустое тело тоже принимается.
struct (0x34813b76) TopUp {
    queryId: uint64
}

// ---------- события (внешние сообщения из Vault; query_id — первым после опкода) ----------

/// Депозит принят Vault'ом, транш ещё стейкается (слот назначит аккаунт).
struct (0x85b4434a) LogDeposited {
    queryId: uint64
    owner: address
    account: address
    principal: coins
}

/// Транш подтверждён стейком: с этого момента он существует в слоте.
struct (0xd4592eba) LogTrancheActivated {
    queryId: uint64
    owner: address
    slot: uint8
    principal: coins
    tokens: coins
    memberJoined: bool
    memberCount: uint32
}

/// Депозит не удался (bounce пула или нет слота: slot = 255), principal снят с total_principal.
struct (0x1da026e0) LogTrancheCancelled {
    queryId: uint64
    owner: address
    principal: coins
    slot: uint8
}

struct (0x72d5e9ca) LogExitStarted {
    queryId: uint64
    owner: address
    mode: uint2
    slots: uint64
    principalSum: coins
    bonus: coins
}

struct (0x9f2b0f1e) LogExitRejected {
    queryId: uint64
    owner: address
    nextWindowAt: uint32
}

struct (0x72208540) LogExited {
    queryId: uint64
    owner: address
    mode: uint2
    slots: uint64
    payout: coins
    forfeit: coins
    hasTranches: bool
    memberCount: uint32
}

struct (0x344b89ee) LogForfeitStaked {
    queryId: uint64
    amount: coins
}

/// Отправить событие как внешнее сообщение; topic = опкод структуры.
fun emitLog<T>(topic: int, body: T) {
    val msg = createExternalLogMessage({
        dest: ExtOutLogBucket { topic },
        body,
    });
    msg.send(SEND_MODE_REGULAR);
}

import "constants"

/// Неизменяемые параметры протокола; одна ячейка, общая для Vault и всех аккаунтов (init-данные).
struct AccountParams {
    pool: address
    tstonMaster: address
    tstonWalletCode: cell
}

// ---------- Vault ----------

struct VaultStorage {
    period: uint32        // секунды между окнами, неизменяемо
    windowLength: uint32  // секунды, сколько окно открыто, неизменяемо
    epochStart: uint32    // момент отсчёта окон, неизменяемо
    accountCode: cell     // код MemberAccount
    accountParams: Cell<AccountParams>
    memberCount: uint32
    totalPrincipal: coins // сумма principal всех активных траншей
    acc: uint128          // бонус-tsTON на 1 nanoTON principal, ×2^64
    unallocated: coins    // tsTON котла, ещё не разнесённые в acc (некому было)
    forfeitBuffer: coins  // TON форфейтов, ещё не отправленные в стейкинг
    pendingStake: coins   // TON форфейтов, отправленные в пул и ещё не подтверждённые
}

fun VaultStorage.load(): VaultStorage {
    return VaultStorage.fromCell(contract.getData());
}

fun VaultStorage.save(self) {
    contract.setData(self.toCell());
}

// ---------- MemberAccount ----------

struct Tranche {
    queryId: uint64     // query_id депозита (для сопоставления с событиями)
    principal: coins
    depositedAt: uint32 // только для UI и истории
    tokens: coins       // tsTON; 0, пока stake не подтверждён
    acc0: uint128       // снимок Vault.acc в момент депозита
    status: uint2       // TRANCHE_STAKING / ACTIVE / EXITING
}

struct PendingBatch {
    queryId: uint64    // query_id из withdraw владельца (для событий)
    slots: uint64      // маска слотов траншей в батче
    principalSum: coins
    tokensSum: coins
    debtSum: uint256   // Σ principal_i × acc0_i
    mode: uint2        // MODE_AWAITING_ACK / EARLY / FULL
    bonusTokens: coins
    batchId: uint32    // query_id для burn и атрибуции выплаты
    createdAt: uint32  // для RETRY_TIMEOUT
    burnSentAt: uint32 // 0, пока burn не отправлен
    burnValue: coins   // TON, приложенные к burn: пул возвращает их вместе с выплатой
}

struct AccountStorage {
    vault: address
    owner: address
    params: Cell<AccountParams>
    tstonWallet: address? // вычисляется при первом credit_tranche
    usedSlots: uint64     // маска занятых слотов (staking | active | exiting)
    isMember: bool        // учтён в Vault.member_count
    batchSeq: uint32
    tranches: map<uint8, Tranche>
    pending: Cell<PendingBatch>?
}

fun AccountStorage.load(): AccountStorage {
    return AccountStorage.fromCell(contract.getData());
}

fun AccountStorage.save(self) {
    contract.setData(self.toCell());
}

/// Init-данные аккаунта участника: детерминированы из (vault, owner, params).
fun calcAccountInit(
    vault: address,
    owner: address,
    accountCode: cell,
    params: Cell<AccountParams>,
): AutoDeployAddress {
    val data: AccountStorage = {
        vault,
        owner,
        params,
        tstonWallet: null,
        usedSlots: 0,
        isMember: false,
        batchSeq: 0,
        tranches: [],
        pending: null,
    };
    return { workchain: MY_WORKCHAIN, stateInit: { code: accountCode, data: data.toCell() } };
}

fun calcAccountAddress(
    vault: address,
    owner: address,
    accountCode: cell,
    params: Cell<AccountParams>,
): address {
    return calcAccountInit(vault, owner, accountCode, params).calculateAddress();
}

